// Safe local D1 migration runner for TEJA (Windows/macOS/Linux, no shell needed).
//   node scripts/db-migrate.mjs status   read-only: show what would happen
//   node scripts/db-migrate.mjs apply    back up, record already-applied migrations, apply the rest
//
// Why this exists: dist/server/wrangler.json is regenerated by every build and has no
// migrations_dir, so `wrangler d1 migrations ...` looked in dist/server/migrations.
// This script writes its own config (.wrangler/d1-migrate.wrangler.json, git-ignored) that
// points at ./drizzle and uses the SAME database_id as the app, so the CLI and
// `npm run dev` / `npm start` share one local database in .wrangler/state.
import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { planMigrations } from './migration-plan.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const DB_NAME = 'site-creator-d1';
const DB_ID = '00000000-0000-4000-8000-000000000000'; // must equal vite.config.ts
const BINDING = 'DB';
const persist = '.wrangler/state';
const cfgPath = path.join(root, '.wrangler', 'd1-migrate.wrangler.json');
const wranglerJs = path.join(root, 'node_modules', 'wrangler', 'bin', 'wrangler.js');
const command = process.argv[2] ?? 'status';

function fail(msg) { console.error('ERROR: ' + msg); process.exit(1); }
if (!['status', 'apply'].includes(command)) fail('Usage: node scripts/db-migrate.mjs <status|apply>');
if (!existsSync(wranglerJs)) fail('Wrangler is not installed. Run "pnpm install --frozen-lockfile" (or "npm install") first.');

const migrationsDir = path.join(root, 'drizzle');
const files = readdirSync(migrationsDir).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();
if (!files.length) fail('No migration files found in ./drizzle');

mkdirSync(path.dirname(cfgPath), { recursive: true });
writeFileSync(cfgPath, JSON.stringify({
  name: 'teja-migrate',
  compatibility_date: '2026-05-15',
  d1_databases: [{ binding: BINDING, database_name: DB_NAME, database_id: DB_ID, migrations_dir: migrationsDir }],
}, null, 2));

function wrangler(args, { json = false } = {}) {
  const full = ['--import', './scripts/sites-env.mjs', wranglerJs, ...args, '--config', cfgPath];
  const r = spawnSync(process.execPath, full, { cwd: root, encoding: 'utf8', stdio: json ? ['ignore', 'pipe', 'pipe'] : 'inherit' });
  return r;
}

function query(sql) {
  const r = wrangler(['d1', 'execute', BINDING, '--local', '--persist-to', persist, '--json', '--command', sql], { json: true });
  // On Windows + Node 24 Wrangler may abort at exit with a libuv assertion (UV_HANDLE_CLOSING)
  // AFTER finishing its work. Trust the parsed output, not the exit code.
  const text = (r.stdout || '').trim();
  const start = text.indexOf('[');
  try {
    const parsed = JSON.parse(text.slice(start));
    const block = Array.isArray(parsed) ? parsed[0] : parsed;
    if (block?.success === false) throw new Error('query failed');
    return block?.results ?? [];
  } catch {
    console.error((r.stderr || text || 'no output from wrangler').slice(0, 800));
    fail('Could not read the local D1 database through Wrangler.');
  }
}

function readState() {
  const tables = new Map(query("SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%'").map((r) => [r.name, r.sql]));
  let applied = null;
  if (tables.has('d1_migrations')) applied = new Set(query('SELECT name FROM d1_migrations').map((r) => r.name));
  return { tables, applied };
}

let { tables, applied } = readState();
const plan = planMigrations(files, tables, applied);
console.log(`Local D1 database: ${DB_NAME} (${persist})`);
console.log(`Tables present: ${[...tables.keys()].filter((t) => t !== 'd1_migrations').length}; migrations recorded: ${applied ? applied.size : 0}/${files.length}`);
console.log('Plan: ' + plan.action);
if (plan.baseline.length) console.log('  Already in schema, will be recorded without re-running: ' + plan.baseline.join(', '));
if (plan.pending.length) console.log('  Will be applied: ' + plan.pending.join(', '));
for (const p of plan.problems) console.log('  PROBLEM: ' + p);

if (plan.action === 'refuse') fail('Database state is inconsistent with ./drizzle. Nothing was changed. Back up .wrangler/state and inspect it (see README, Troubleshooting).');
if (command === 'status' || plan.action === 'noop') { if (plan.action === 'noop') console.log('Database is up to date.'); process.exit(0); }

const stateDir = path.join(root, persist, 'v3', 'd1');
if (existsSync(stateDir)) {
  const backup = path.join(root, '.wrangler', 'backups', 'd1-' + new Date().toISOString().replace(/[:.]/g, '-'));
  cpSync(stateDir, backup, { recursive: true });
  console.log('Backup written to ' + path.relative(root, backup));
}

if (plan.baseline.length) {
  const values = plan.baseline.map((n) => `('${n.replace(/'/g, "''")}')`).join(',');
  query('CREATE TABLE IF NOT EXISTS d1_migrations(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  query(`INSERT OR IGNORE INTO d1_migrations(name) VALUES ${values}`);
}
if (plan.pending.length) wrangler(['d1', 'migrations', 'apply', BINDING, '--local', '--persist-to', persist]);

({ tables, applied } = readState());
const after = planMigrations(files, tables, applied);
if (after.action !== 'noop') fail('Migrations are not fully applied. Plan after run: ' + after.action + ' ' + (after.pending.join(', ') || after.problems.join('; ')));
console.log('OK: all ' + files.length + ' migrations are applied.');
process.exit(0);
